WITH with_last AS (SELECT s.id, s.customer_id, s.status, s.channel, s.amount, s.discount, x.payment_amount FROM orders s LEFT JOIN LATERAL (SELECT c.amount AS payment_amount FROM payments c WHERE c.order_id = s.id ORDER BY c.amount DESC, c.id DESC LIMIT 1) x ON TRUE) SELECT id, status, channel, discount, CASE WHEN channel RLIKE '^(partner|store)$' THEN 'GROUP_B' WHEN channel RLIKE '^(web|mobile)$' THEN 'PRIORITY' ELSE 'GROUP_A' END AS channel_zone FROM with_last
